import React from 'react';
import { BrowserRouter as Router, Route, Switch } from 'react-router-dom';
import NavBar from './Components/NavBar';
import About from './Components/About/About';


const App = () => {
  return (
    <Router>
      <NavBar />
      <Switch>
      <Route path="/about" component={About} />
      </Switch>
    </Router>
  );
};

export default App;
